'use strict';
class MonthlyCharts{
 constructor(){this.worker=new Worker('monthly-worker.js?v=24');this.id=0;this.key='';this.months=null;this.worker.onmessage=({data:d})=>{if(d.id!==this.id)return;if(d.error){this.clear('Monthly data could not load. Select this location again to retry.');return;}this.months=d.months;this.render();};document.getElementById('monthly-mode').onchange=()=>this.render();}
 clear(message){this.id++;this.key='';this.months=null;document.getElementById('monthly-status').textContent=message;document.getElementById('monthly-plots').replaceChildren();document.getElementById('monthly-table').replaceChildren();}
 select(node,period,params,sunshine,name,lat,lon){const key=JSON.stringify([node,period,params]);document.getElementById('monthly-title').textContent=`${name} through the year`;document.getElementById('monthly-source').textContent=`${period==='mean'?'2020–2025 monthly averages':period} · ERA5 cell ${lat.toFixed(2)}°, ${lon.toFixed(2)}° · UTC days · Open-Meteo daily API`;if(key===this.key)return;this.clear('Loading this climate cell’s monthly records…');this.key=key;this.params={...params};this.worker.postMessage({id:this.id,node,period,params,latitude:lat,longitude:lon});}
 render(){if(!this.months)return;const labels=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],mode=document.getElementById('monthly-mode').value;document.getElementById('monthly-status').textContent='Monthly averages · hover or focus a value to inspect. Gaps mean insufficient records.';const plots=document.getElementById('monthly-plots');plots.replaceChildren();for(const spec of [{key:'temperature',title:'Average daily high',unit:'°C',kind:'line',color:'#0a2463',band:[this.params.lower,this.params.upper]},{key:'minimumTemperature',title:'Daily low',unit:'°C',kind:'line',color:'#167aaf'},{key:'humidity',title:'Humidity',unit:'%',kind:'line',color:'#167aaf'},{key:'hotNights',title:'Warm nights · minimum ≥20°C',unit:'days / month',kind:'bar',color:'#967300'},{key:'precipitation',title:'Monthly precipitation',unit:'mm / month',kind:'bar',color:'#2da0e0'},{key:'sunshine',title:'Daily sunshine',unit:'hours / day',kind:'line',color:'#967300',band:this.params.sunenabled?[this.params.sunmin,24]:null}]){const article=document.createElement('article'),h=document.createElement('h3');h.textContent=spec.title;article.append(h);if(mode==='heatmap'){const grid=document.createElement('div');grid.className='monthly-heatmap';const finite=this.months.map(m=>m[spec.key]).filter(v=>v!==null),low=Math.min(...finite),high=Math.max(...finite),rgb=spec.color.slice(1).match(/../g).map(v=>parseInt(v,16)),linear=v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;};this.months.forEach((m,i)=>{const cell=document.createElement('div'),label=document.createElement('span'),value=document.createElement('strong'),v=m[spec.key];label.textContent=labels[i];value.textContent=v===null?'—':v.toFixed(1);cell.append(label,value);if(v!==null){const alpha=high>low?.15+.85*(v-low)/(high-low):.5,color=rgb.map(c=>Math.round(255*(1-alpha)+c*alpha)),L=.2126*linear(color[0])+.7152*linear(color[1])+.0722*linear(color[2]);cell.style.backgroundColor=`rgb(${color.join(',')})`;cell.style.color=(L+.05)/.059>(1.05/(L+.05))?'#061640':'#fff';}cell.setAttribute('aria-label',`${labels[i]}: ${v===null?'Not available':v.toFixed(1)+' '+spec.unit}`);grid.append(cell);});article.append(grid);const note=document.createElement('p');note.className='chart-note';note.textContent=`${spec.unit} · darker color means a higher value within this chart.${spec.key==='temperature'?' Cells show average daily high; daily means are in the table.':''}`;article.append(note);plots.append(article);continue;}const readout=document.createElement('p');readout.className='chart-readout';readout.textContent='Hover a month, or focus a data point, to inspect.';const finite=this.months.flatMap(m=>spec.key==='temperature'?[m.temperature,m.meanTemperature]:[m[spec.key]]).filter(v=>v!==null),low=Math.min(0,...finite,...(spec.band||[])),high=Math.max(1,...finite,...(spec.band||[]))*1.1;const width=620,height=210,left=54,right=18,top=15,bottom=34,W=width-left-right,H=height-top-bottom,x=i=>left+(i+.5)*W/12,y=v=>top+H-(v-low)/(high-low)*H;const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('role','img');svg.setAttribute('aria-label',`${spec.title}, ${spec.unit}. Values are also available in the table.`);const el=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;svg.append(e);return e;};for(let i=0;i<4;i++){const value=low+(high-low)*i/3;el('line',{x1:left,y1:y(value),x2:width-right,y2:y(value),stroke:'#d8dfeb'});el('text',{x:left-9,y:y(value)+4,'text-anchor':'end',fill:'#50617d','font-size':11},value.toFixed(spec.key==='sunshine'?1:0));}if(spec.band&&mode!=='heatmap'){el('rect',{x:left,y:y(spec.band[1]),width:W,height:y(spec.band[0])-y(spec.band[1]),fill:'#f5c518','fill-opacity':.18});for(const b of spec.band)el('line',{x1:left,y1:y(b),x2:width-right,y2:y(b),stroke:'#967300','stroke-dasharray':'4 4'});}let segments=[];this.months.forEach((m,i)=>{const v=m[spec.key];el('text',{x:x(i),y:height-12,'text-anchor':'middle',fill:'#50617d','font-size':11},labels[i]);if(v===null){segments=[];return;}let mark;if(mode==='heatmap'){mark=el('rect',{x:left+i*W/12+2,y:top+20,width:W/12-4,height:H-38,fill:spec.color,'fill-opacity':.15+.85*(v-low)/(high-low),rx:3});el('text',{x:x(i),y:top+H/2+3,'text-anchor':'middle',fill:spec.key==='temperature'&&v>(low+high)/2?'#fff':'#061640','font-size':12},v.toFixed(1));}else if(spec.kind==='bar')mark=el('rect',{x:x(i)-W/36,y:y(v),width:W/18,height:y(0)-y(v),fill:spec.color,rx:3});else{if(segments.length)el('line',{x1:segments[0],y1:segments[1],x2:x(i),y2:y(v),stroke:spec.color,'stroke-width':2.5});segments=[x(i),y(v)];mark=el('circle',{cx:x(i),cy:y(v),r:4,fill:spec.color});}const title=document.createElementNS(ns,'title');title.textContent=`${labels[i]}: ${v.toFixed(1)} ${spec.unit}`;mark.append(title);mark.setAttribute('tabindex','0');mark.setAttribute('aria-label',title.textContent);mark.addEventListener('pointerenter',()=>{readout.textContent=title.textContent;});mark.addEventListener('focus',()=>{readout.textContent=title.textContent;});});el('text',{x:left,y:12,fill:'#50617d','font-size':11},spec.unit);if(spec.key==='temperature'&&mode!=='heatmap'){let prev=null;this.months.forEach((m,i)=>{if(m.meanTemperature===null){prev=null;return;}if(prev)el('line',{x1:prev[0],y1:prev[1],x2:x(i),y2:y(m.meanTemperature),stroke:'#167aaf','stroke-width':2,'stroke-dasharray':'5 4'});prev=[x(i),y(m.meanTemperature)];const mark=el('circle',{cx:x(i),cy:y(m.meanTemperature),r:3,fill:'#167aaf',tabindex:0,'aria-label':labels[i]+': daily mean '+m.meanTemperature.toFixed(1)+' °C'});mark.addEventListener('pointerenter',()=>readout.textContent=mark.getAttribute('aria-label'));mark.addEventListener('focus',()=>readout.textContent=mark.getAttribute('aria-label'));});}const scroll=document.createElement('div');scroll.className='chart-scroll';scroll.tabIndex=0;scroll.setAttribute('aria-label','Scrollable '+spec.title+' chart');scroll.append(svg);article.append(scroll,readout);if(spec.band){const note=document.createElement('p');note.className='chart-note';note.textContent=spec.key==='temperature'?`${mode==='heatmap'?'Cells: average daily high.':'Solid: daily high; dashed: daily mean.'} Shaded range: your ${this.params.lower}–${this.params.upper}°C daily comfort band. A monthly average inside it does not mean every day qualifies.`:`Shaded range starts at your ${this.params.sunmin} h/day minimum.`;article.append(note);}plots.append(article);}const table=document.getElementById('monthly-table');table.replaceChildren();const head=document.createElement('thead'),tr=document.createElement('tr');for(const text of ['Month','Daily high °C','Daily mean °C','Daily low °C','Humidity %','Warm nights ≥20°C','Precipitation mm/month','Sunshine h/day']){const th=document.createElement('th');th.scope='col';th.textContent=text;tr.append(th);}head.append(tr);table.append(head);const body=document.createElement('tbody');this.months.forEach((m,i)=>{const row=document.createElement('tr');for(const value of [labels[i],...['temperature','meanTemperature','minimumTemperature','humidity','hotNights','precipitation','sunshine'].map(k=>m[k]===null?'Not available':m[k].toFixed(1))]){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}body.append(row);});table.append(body);}
}
window.MonthlyCharts=MonthlyCharts;
